/*
 * The parts of the Itanium C++ ABI's unwinder that a C166 program can use.
 * The shape is the standard one so that code generated for it links, and the
 * differences from a hosted unwinder are the two the part forces:
 *
 *   - There is no dynamic loader to ask where the unwind tables are, so they
 *     are found between __eh_frame_start and __eh_frame_end, which the linker
 *     script defines.
 *
 *   - A return address is not in a register and not in this frame.  It is on
 *     the system stack, which is a second stack the compiler never touches,
 *     and the call frame information says so with a DWARF expression rather
 *     than an offset.  Unwinding a frame therefore restores two stack
 *     pointers, and the code segment pointer with them.
 */

#ifndef C166_UNWIND_H
#define C166_UNWIND_H

typedef unsigned char _uw8;
typedef unsigned short _uw16;
typedef unsigned long _uw32;

typedef enum {
  _URC_NO_REASON = 0,
  _URC_FOREIGN_EXCEPTION_CAUGHT = 1,
  _URC_FATAL_PHASE2_ERROR = 2,
  _URC_FATAL_PHASE1_ERROR = 3,
  _URC_NORMAL_STOP = 4,
  _URC_END_OF_STACK = 5,
  _URC_HANDLER_FOUND = 6,
  _URC_INSTALL_CONTEXT = 7,
  _URC_CONTINUE_UNWIND = 8
} _Unwind_Reason_Code;

typedef struct _Unwind_Context _Unwind_Context;
typedef struct _Unwind_Exception _Unwind_Exception;

/* Which pass over the stack a personality routine is being called for. */
#define _UA_SEARCH_PHASE  1
#define _UA_CLEANUP_PHASE 2
#define _UA_HANDLER_FRAME 4
#define _UA_FORCE_UNWIND  8

/* The header the language runtime puts in front of a thrown object.  The
 * layout is this target's own: nothing generated by the compiler reaches into
 * it, only __cxa_throw and the personality routine, and they are both here.
 * The exception class is thirty two bits rather than the sixty four a hosted
 * ABI uses, which is enough to tell this runtime's exceptions from anything
 * else that might one day be thrown through it. */
struct _Unwind_Exception {
  _uw32 exception_class;
  void (*exception_cleanup)(_Unwind_Reason_Code, _Unwind_Exception *);
  _uw32 private_1; /* the handler frame, found in the search pass */
  _uw32 private_2; /* the landing pad it will enter              */
};

typedef _Unwind_Reason_Code (*_Unwind_Personality_Fn)(int version, int actions,
                                                      _uw32 exceptionClass,
                                                      _Unwind_Exception *exc,
                                                      _Unwind_Context *ctx);

/* Where the unwinder is in a walk: one frame's register state, and the rules
 * that produced it.  A program sees this only as an opaque pointer. */
struct _Unwind_Context {
  _uw16 reg[16];   /* R0 to R15; R0 is the ABI stack pointer.               */
  _uw16 syssp;     /* The system stack pointer, which holds return          */
                   /* addresses and which no generated code touches.        */
  _uw16 csp;       /* The code segment this frame runs in.                  */
  _uw32 pc;        /* CSP:IP, the 24 bit address, zero extended.            */
  _uw32 cfa;       /* The canonical frame address, which here is the        */
                   /* caller's R0.                                          */
  _uw32 fde;       /* The frame description entry the rules came from, or 0 */
                   /* if the walk has not looked one up yet.                */
  _uw32 lsda;      /* Its language specific data area, or 0.                */
  _uw32 start;     /* Where the function the frame is in begins.            */
};

_Unwind_Reason_Code _Unwind_RaiseException(_Unwind_Exception *exc);
void _Unwind_Resume(_Unwind_Exception *exc);
void _Unwind_DeleteException(_Unwind_Exception *exc);
_uw32 _Unwind_GetCFA(_Unwind_Context *ctx);

_Unwind_Reason_Code _Unwind_Backtrace(_Unwind_Reason_Code (*fn)(_Unwind_Context *,
                                                                void *),
                                      void *arg);

_uw32 _Unwind_GetIP(_Unwind_Context *ctx);
void _Unwind_SetIP(_Unwind_Context *ctx, _uw32 pc);
_uw32 _Unwind_GetGR(_Unwind_Context *ctx, int reg);
void _Unwind_SetGR(_Unwind_Context *ctx, int reg, _uw32 value);
_uw32 _Unwind_GetRegionStart(_Unwind_Context *ctx);
_uw32 _Unwind_GetLanguageSpecificData(_Unwind_Context *ctx);

/* Fill ctx with the register state of whoever called this.  Written in
 * assembly, because it is about registers the compiler is using. */
void __unw_getcontext(_Unwind_Context *ctx);

/* Step ctx back one frame.  _URC_END_OF_STACK when there is no caller. */
_Unwind_Reason_Code __unw_step(_Unwind_Context *ctx);

/* Fill in what a personality routine is told about the frame ctx is already
 * in, without stepping out of it.  Zero when nothing describes it. */
int __unw_describe(_Unwind_Context *ctx);

/* Put the machine into the state ctx describes and carry on there.  Written
 * in assembly, and does not return. */
void __unw_resume(_Unwind_Context *ctx);

/* Where a personality routine lives, for the frame ctx is in. */
_uw32 __unw_personality(_Unwind_Context *ctx);

#endif /* C166_UNWIND_H */
